import Immutable from "immutable"
import * as Project from "../project"
import * as Timeline from "./index.ts"
import Rational from "../utils/rational.ts"
import Range from "../utils/range.ts"
import Rect from "../utils/rect.ts"


export interface State
{
    pixelRatio: number
    renderRect: Rect

    trackMeasuresH: number
    trackControlX: number
    trackControlY: number
    trackControlSize: number

    layout: Timeline.Layout
    hover: Timeline.LayoutElement | undefined
    
    yScroll: number
    timeScroll: number
    timeScale: number
    timeSnap: Rational
    timeSnapBase: Rational

    noteRowH: number

    cursor:
    {
        visible: boolean
        time1: Rational
        time2: Rational
        laneIndex1: number
        laneIndex2: number
        rectY1: number
        rectY2: number
    }

    keysDown: Set<string>,

    mouse:
    {
        down: boolean
        downDate: Date

        action: MouseAction

        point: Point
        pointPrev: Point

        wheelDate: Date
    }

    drag:
    {
        origin:
        {
            point: Point
            range: Range | null
            timeScroll: number
            yScroll: number
            project: Project.ImmutableRoot
        }

        xLocked: boolean
        yLocked: boolean

        posDelta: { x: number, y: number }
        timeDelta: Rational
        rowDelta: number
        trackDelta: number
        trackInsertionBefore: number

        elemId: Project.ID
        notePreviewLast: number | null
    }

    insertion:
    {
        nearMidiPitch: number
        duration: Rational
    }

    selection: Immutable.Set<Project.ID>

    needsKeyFinish: boolean
    rangeSelectOriginTrackIndex: number
}


export enum MouseAction
{
    None,
    Pan,
    DragTime,
    DragRow,
    DragTimeAndRow,
    StretchTimeStart,
    StretchTimeEnd,
    SelectCursor,
}


export interface Point
{
    pos: { x: number, y: number }
    time: Rational
    row: number
    laneIndex: number
    trackPos: { x: number, y: number }
    originTrackPos: { x: number, y: number }
}


export interface HoverData
{
    id: Project.ID
    range: Range
    action: MouseAction
}



